class Base:
    def __init__(self):
        self.__value = "base"

class Child(Base):
    def __init__(self):
        super().__init__()
        self.__value = "child"

c = Child()
print(c._Base__value)
print(c._Child__value)

class Product:
    def __init__(self, name: str, price: float):
        self.name = name
        self.price = price

    @property
    def price(self) -> float:
        return self._price

    @price.setter
    def price(self, value: float) -> None:
        if value < 0:
            raise ValueError("price must be nonnegative")
        self._price = round(value, 2)

book = Product("Python OOP", 580.126)
print(book.price)

class BadProduct:
    @property
    def price(self):
        return self._price

    @price.setter
    def price(self, value):
        self.price = value

try:
    BadProduct().price = 10
except RecursionError:
    print("recursive setter")

class BadProduct:
    def __init__(self):
        self._price = 100

    def set_price(self, value):
        self._price = value
        if value < 0:
