@require_http_methods(["GET", "POST"])
def product_create(request):
    if request.method == "POST":
        form = ProductForm(request.POST)
        if form.is_valid():
            form.save()
            return redirect("catalog:product_list")
    else:
        form = ProductForm()
    return render(request,
        "catalog/product_form.html",
        {"form": form})

