def _download(path, expected_hash=None):
    with urlopen(DATA_ROOT + path, timeout=10) as response:
        content = response.read()
    if expected_hash:
        actual = hashlib.sha256(content).hexdigest()
        if actual != expected_hash:
            raise QuoteError("匯率資料的檢查碼不符")
    return json.loads(content)

