from django.http import HttpResponse
from .models import Post

def homepage(request):
    posts = Post.objects.all()
    lines = [
        f"{i}. {post.title}"
        for i, post in enumerate(posts, start=1)
    ]
    return HttpResponse(
        "\n".join(lines),
        content_type="text/plain; charset=utf-8",
    )

