from django.conf import settings
from .common import AIError, SYSTEM_PROMPT, checked_text

def create_response(client, prompt):
    return client.responses.create(
        model=settings.OPENAI_MODEL,
        instructions=SYSTEM_PROMPT, input=prompt,
        reasoning={"effort": "none"}, max_output_tokens=600,
        store=False, stream=False,
    )

def response_text(response):
    if getattr(response, "status", None) != "completed":
        raise AIError("incomplete", "回答が未完了です。質問の範囲を絞って再試行してください。")
    return checked_text(getattr(response, "output_text", None))

from .sdk_common import make_client, sdk_call
OPENAI_BASE_URL = "https://api.openai.com/v1"

class OpenAIProvider:
    def generate(self, prompt):
        with make_client(settings.OPENAI_API_KEY, "OpenAI", OPENAI_BASE_URL) as client:
            response = sdk_call(lambda: create_response(client, prompt))
        return response_text(response)

from django.conf import settings
from .common import AIError, chat_messages, checked_text

def create_completion(client, prompt):
    return client.chat.completions.create(
        model=settings.NVIDIA_MODEL, messages=chat_messages(prompt),
        max_tokens=600, stream=False,
        extra_body={"chat_template_kwargs": {"enable_thinking": False}},
    )

from .sdk_common import make_client, sdk_call
NVIDIA_BASE_URL = "https://integrate.api.nvidia.com/v1"

def completion_text(completion):
    choices = getattr(completion, "choices", None)
    if not isinstance(choices, list) or not choices:
        raise AIError("format", "NVIDIA 有効な choices が返されませんでした。")
    if getattr(choices[0], "finish_reason", None) == "length":
        raise AIError("incomplete", "回答が長さの上限に達しました。質問の範囲を絞って再試行してください。")
    message = getattr(choices[0], "message", None)
    return checked_text(getattr(message, "content", None))

class NvidiaProvider:
    def generate(self, prompt):
        with make_client(settings.NVIDIA_API_KEY, "NVIDIA", NVIDIA_BASE_URL) as client:
            completion = sdk_call(lambda: create_completion(client, prompt))
        return completion_text(completion)

def sdk_error(exc):
    if isinstance(exc, openai.APITimeoutError):
        return AIError("timeout", "クラウドサービスがタイムアウトしました。後で再試行してください。")
    if isinstance(exc, openai.APIConnectionError):
        return AIError("connection", "クラウドサービスに接続できません。ネットワークを確認してください。")
    status = getattr(exc, "status_code", None)
    if status in (401, 403):
        return AIError("auth", "API キーとモデルの利用権限を確認してください。")
    if status == 429:
        return AIError("rate_limit", "速度または利用枠の上限です。プランを確認し、後で再試行してください。")
    if status == 404:
        return AIError("model", "モデルが見つかりません。ID と権限を確認してください。")
    return AIError("api", "クラウド API エラーです。サービス状態と設定を確認してください。")

def sdk_call(operation):
    try:
        return operation()
    except openai.OpenAIError as exc:
        raise sdk_error(exc) from None
    except ValueError:
        raise AIError("json", "クラウドの応答を解析できません。後で再試行してください。") from None

def get_provider(name) -> TextProvider:
    provider_class = PROVIDERS.get(name)
    if provider_class is None:
        raise AIError("provider", "未対応のサービスです。")
    return provider_class()

